static void saveProfile(void){if(!storage)return;char p[96];filePath(p,"profile.dat");FILE*f=fopen(p,"wb");if(f){fwrite(profile,sizeof profile,1,f);fwrite(&unlocked,sizeof unlocked,1,f);fclose(f);}}

