typedef struct {int d; const char *name,*pic,*bio;} Preset;
static const Preset presets[]={{0,"Adam","Adam","Hybrid Human (Human, Immortal), about 25. Quick to anger and overprotective. Adopted at 14 by Leilani and Arnold. Siblings Ryan-Lucas, CatRina and Amanda. Biarra L'Oscuro was his ex-wife across many lives."},{0,"Leilani Cartez","Leilani","Grew up poor and climbed to the top. Despises Biarra. Guarded toward you unless Adam, CatRina or Amanda is present."},{0,"Arnold Cartez","Arnold","Bitter old man. Skeptical because you know Bia. His wife calls the shots."},{0,"CatRina Cartez","CatRina","23. Black cat energy. Married Michael; daughter Catalina. Friendly, supportive, often depressed. Loves purple."},{0,"Amanda Cartez","Amanda","Blonde mother of four boys. Ivan is a soldier fighting the War on Darkness."},{0,"Alizon","Alizon","Ryan-Lucas' ex-wife. Married Marvin. Named their daughter Bia after her former enemy. About 14 children with Ryan-Lucas and one with Marvin."},{0,"Sheila Dantino","Sheila","Cousin to the Cartez children. Does not want children. Loves pink."},{0,"Aisling Aenira Cartez","Aisling","Daughter of Biarra and Ryan-Lucas. Runs her own veterinary clinic. Sees Adam as a father figure and never liked Ryan-Lucas. Kind."},{0,"Rose","Rose","Granddaughter of Ryan-Lucas and Biarra. Mother Mira Rose died in a car accident the day Rose was born. Kidnapped, she had a son Nightmare and turned him into a kitten to save him. Married childhood friend Sophie."},{2,"Killian Joneson","Killian","King of the Underworld. His heart belongs to departed wife Biarra, the Dark One. Friendly to you. Former drinking problem."},{2,"Jacob Joneson","Jacob","Killian's older brother. Rules his own part of the Underworld. Nasty and likely to hurt you."},{2,"Luciferin the Great","Luciferin","Highest ruler of the Underworld. Father of Killian and Jacob. Fond of Biarra. Best friend of her father L'Oscuro."},{3,"Joshua Redford","Jesse","Formerly Jesse Pinkman. Started a new life after trauma. Likes computers. Once loved Biarra, calling her Babydoll."},{3,"Jackson Vito","Jackson","Lyric's father. Ex-wife Angelica Francisco. You met at a bar."},{3,"Lyric Vito","Lyric","Jackson's daughter."},{3,"Angelica Francisco","Angelica","Jackson Vito's ex-wife."},{3,"Cristello Vax","Cristello","Mafia heir."},{3,"Santino Dorino","Santino","Mid-twenties. Grew up in an Italian household. A good guy and overprotective."},{4,"Janine","Janine","TJ's aunt. Runs the Homicide Unit. Strict but kind."},{4,"TJ","TJ","Single, mid-twenties. Daughter Fiora. Biarra kept him away from her. Read Hardly Human: Breaking Point."},{4,"Frankino","Franky","TJ's uncle. Runs the Homicide Unit. Funny, married, father figure."},{4,"Angelo Bradford","Angelo","Son of Tim Bradford and Lucy Chen."},{5,"Regina Miller","Regina","Former Evil Queen. Married Robin, daughter Cassanova. Gave Biarra to Kellina and Carlisle. Mother figure and magic mentor."},{5,"Zelena Miller","Zelena","Regina's older sister. Wicked, not evil. Fun aunt type. Protective."},{5,"Emma Thornton","Emma","Killian's ex-wife. Mother of Hope and Henry. Henry saw Biarra as a big sister."},{5,"Granny","Granny","Runs the diner. Loves gossip and makes pie on a bad day."},{5,"Rebekah","Rebekah","Granny's granddaughter. Part werewolf. Hunts with wife Alexandra. Good friend but sometimes angry."},{6,"Ocean Munson","Ocean","Daughter of Killian and Biarra. Hidden from the world for unknown reasons. Married Eddie after accidentally meeting him and nearly blasting his head off."},{6,"Eddie Munson","Eddie","Metalhead, Corroded Coffin guitarist and Hellfire Club leader. Rebellious, funny and caring. Accidentally met Ocean, who nearly blasted his head off. They married."},{7,"Gizmo","Gizmo","A boy cat who would love to hear what you have to say."},{8,"Ryan-Lucas","Ryan-Lucas","We miss you, Ryan-Lucas. Rest In Peace. 2001-2025."},{8,"Ashley","Ashley","We miss you, Ash... May you rest in peace wherever you are. 2002-2024"},{8,"Ambrose Hale","Ambrose","Until we (NEVER) meet again... Unknown-2025"}};
#define NP (sizeof presets/sizeof presets[0])
static int pd=0,pi=0,bs=0;
static int findpreset(const char*n){for(int i=0;i<NP;i++)if(!strcasecmp(n,presets[i].name))return i;return -1;}
static int nextpreset(int from,int step){for(int i=from+step;i>=0&&i<NP;i+=step)if(presets[i].d==pd)return i;return from;}
static int firstpreset(void){for(int i=0;i<NP;i++)if(presets[i].d==pd)return i;return -1;}
static int prison(void){return count>0&&!strcasecmp(names[sel],"Ryan-Lucas");}
static void save(void){if(!storage)return; char p[96];filePath(p,"contacts.dat");FILE*f=fopen(p,"wb");if(!f){strcpy(notice,"Save failed");return;} fwrite(&count,sizeof count,1,f);fwrite(names,sizeof names,1,f);fwrite(dims,sizeof dims,1,f);fwrite(draft,sizeof draft,1,f);if(fclose(f))strcpy(notice,"Save failed");}
static void load(void){char p[96];filePath(p,"contacts.dat");FILE*f=fopen(p,"rb");if(!f)return; if(fread(&count,sizeof count,1,f)!=1||count<0||count>N||fread(names,sizeof names,1,f)!=1||fread(dims,sizeof dims,1,f)!=1||fread(draft,sizeof draft,1,f)!=1)count=0;fclose(f);for(int i=0;i<count;i++){names[i][31]=0;dims[i][23]=0;draft[i][LEN-1]=0;}}
static void chooseUser(int u){user=u;snprintf(root,sizeof root,"/Dimensionz/%s",users[u]);count=sel=0;unlocked=0;memset(names,0,sizeof names);memset(dims,0,sizeof dims);memset(draft,0,sizeof draft);memset(profile,0,sizeof profile);if(storage){mkdir(root,0777);load();char p[96];filePath(p,"profile.dat");FILE*f=fopen(p,"rb");if(f){if(fread(profile,sizeof profile,1,f)!=1)memset(profile,0,sizeof profile);if(fread(&unlocked,sizeof unlocked,1,f)!=1)unlocked=0;fclose(f);}}for(int i=0;i<4;i++)profile[i][LEN-1]=0;mode=profile[0][0]?0:6;profileField=0;strcpy(input,profile[0]);}
static void path(char*p){sprintf(p,"%s/chat%02d.txt",root,sel);}
static int heaven(void){return count>0&&!strcasecmp(dims[sel],"Heaven");}
static void append(char side){if(!input[0])return;if(prison()&&(side=='N'||strchr(input,'*'))){strcpy(notice,"Communication only. No roleplay");return;}if(!storage){strcpy(notice,"SD unavailable; not saved");return;}char p[96];path(p);FILE*f=fopen(p,"a");if(!f){strcpy(notice,"Cannot open chat file");return;}time_t now=time(NULL);struct tm*t=localtime(&now);char stamp[32]="Unknown time";if(t)strftime(stamp,sizeof stamp,"%m/%d/%y %H:%M",t);int ok;if(side=='N'){ok=fprintf(f,"Narration %s\n",stamp);for(int j=0;ok>=0&&input[j];){int len=strlen(input+j);if(len>31)len=31;ok=fprintf(f,"%*s%.*s\n",(31-len)/2,"",len,input+j);j+=len;}}else ok=fprintf(f,"%c %s\n%s\n",side,stamp,input);int closed=fclose(f);if(ok<0||closed){strcpy(notice,"Save failed");return;}if(side=='>'&&!strcasecmp(names[sel],"Aisling Aenira Cartez")&&!unlocked){char q[LEN];strcpy(q,input);int n=strlen(q);while(n&&strchr(" .!?",q[n-1]))q[--n]=0;if(!strcasecmp(q,"I miss Ryan")||!strcasecmp(q,"I miss your father")||!strcasecmp(q,"I miss Ryan-Lucas")){unlocked=1;saveProfile();mode=13;}}input[0]=0;draft[sel][0]=0;save();scroll=0;strcpy(notice,"Saved to SD");}
static void removeChat(void){
 if(!storage||sel<0||sel>=count)return;
 char a[96],b[96]; int old=sel; path(a); FILE*f=fopen(a,"r"); if(f){fclose(f);if(remove(a)){strcpy(notice,"Remove failed");return;}}
 for(int i=old+1;i<count;i++){snprintf(a,sizeof a,"%s/chat%02d.txt",root,i);snprintf(b,sizeof b,"%s/chat%02d.txt",root,i-1);f=fopen(a,"r");if(f){fclose(f);if(rename(a,b)){strcpy(notice,"Move failed");return;}}}
 for(int i=old;i<count-1;i++){memcpy(names[i],names[i+1],32);memcpy(dims[i],dims[i+1],24);memcpy(draft[i],draft[i+1],LEN);} count--;memset(names[count],0,32);memset(dims[count],0,24);memset(draft[count],0,LEN);if(sel>=count)sel=count?count-1:0;save();mode=0;
}
static void add(char c){size_t n=strlen(input);if(n<LEN-1){input[n]=c;input[n+1]=0;}}
static void back(void){size_t n=strlen(input);if(n)input[n-1]=0;}
static void leave(void){if(mode==1||mode==3||mode==8){strcpy(draft[sel],input);save();}mode=0;input[0]=0;scroll=0;}
static void openchat(void){if(!count)return;notice[0]=0;mode=1;narrator=0;strcpy(input,draft[sel]);scroll=0;}

